      "footnotesUr": "[1] اسی احسان کے ساتھ دوسرے احسان کا ذکر فرمایا کہ چوپائے (اونٹ، گائے اور بکریاں) بھی اسی نے پیدا کئے، جن کے بالوں اور اون سے تم گرم کپڑے تیار کر کے گرمی حاصل کرتے ہو۔ اسی طرح ان سے دیگر منافع حاصل کرتے ہو، مثلاً ان سے دودھ حاصل کرتے ہو، ان پر سواری کرتے ہو اور سامان لادتے ہو، ان کے ذریعے ہل چلاتے اور کھیتوں کو سیراب کرتے ہو، وغیرہ وغیرہ۔",
