      "arFull": "وَسَخَّرَ لَكُمُ الَّیْلَ وَالنَّهَارَ ۙ وَالشَّمْسَ وَالْقَمَرَ ؕ وَالنُّجُوْمُ مُسَخَّرٰتٌ بِاَمْرِهٖ ؕ اِنَّ فِیْ ذٰلِكَ لَاٰیٰتٍ لِّقَوْمٍ یَّعْقِلُوْنَ ۟ۙ",
