      "arFull": "اِلٰهُكُمْ اِلٰهٌ وَّاحِدٌ ۚ فَالَّذِیْنَ لَا یُؤْمِنُوْنَ بِالْاٰخِرَةِ قُلُوْبُهُمْ مُّنْكِرَةٌ وَّهُمْ مُّسْتَكْبِرُوْنَ ۟",
      "ur": "تم سب کا معبود صرف اللہ تعالیٰ اکیلا ہے اور آخرت پر ایمان نہ رکھنے والوں کے دل منکر ہیں اور وه خود تکبر سے بھرے ہوئے ہیں.[1]",
      "en": "Your god is one God. But those who do not believe in the Hereafter - their hearts are disapproving, and they are arrogant.",
      "footnotesUr": "[1] یعنی ایک الٰہ کا ماننا منکرین اور مشرکین کے لئے بہت مشکل ہے۔ وہ کہتے ہیں «أَجَعَلَ الآلِهَةَ إِلَهًا وَاحِدًا إِنَّ هَذَا لَشَيْءٌ عُجَابٌ» (ص:5) ”اس نے تمام معبودوں کو ایک ہی معبود کر دیا یہ تو بڑی ہی عجیب بات ہے“، دوسرے مقام پر فرمایا «وَإِذَا ذُكِرَ اللَّهُ وَحْدَهُ اشْمَأَزَّتْ قُلُوبُ الَّذِينَ لا يُؤْمِنُونَ بِالآخِرَةِ وَإِذَا ذُكِرَ الَّذِينَ مِنْ دُونِهِ إِذَا هُمْ يَسْتَبْشِرُونَ» ( الزمر:45) ”جب ایک اللہ کا ذکر کیا جاتا ہے تو منکرین آخرت کے دل تنگ ہو جاتے ہیں اور جب اللہ کے سوا دوسرے معبودوں کا ذکر آ جاتا ہے تو خوش ہوتے ہیں“۔",
      "footnotesEn": null,
