      "number": 29,
      "arFull": "فَادْخُلُوْۤا اَبْوَابَ جَهَنَّمَ خٰلِدِیْنَ فِیْهَا ؕ فَلَبِئْسَ مَثْوَی الْمُتَكَبِّرِیْنَ ۟",
      "ur": "پس اب تو ہمیشگی کے طور پر تم جہنم کے دروازوں میں داخل ہو جاؤ[1] ، پس کیا ہی برا ٹھکانا ہے غرور کرنے والوں کا.",
