      "arFull": "وَقِیْلَ لِلَّذِیْنَ اتَّقَوْا مَاذَاۤ اَنْزَلَ رَبُّكُمْ ؕ قَالُوْا خَیْرًا ؕ لِلَّذِیْنَ اَحْسَنُوْا فِیْ هٰذِهِ الدُّنْیَا حَسَنَةٌ ؕ وَلَدَارُ الْاٰخِرَةِ خَیْرٌ ؕ وَلَنِعْمَ دَارُ الْمُتَّقِیْنَ ۟ۙ",
