      "arFull": "اَفَاَمِنَ الَّذِیْنَ مَكَرُوا السَّیِّاٰتِ اَنْ یَّخْسِفَ اللّٰهُ بِهِمُ الْاَرْضَ اَوْ یَاْتِیَهُمُ الْعَذَابُ مِنْ حَیْثُ لَا یَشْعُرُوْنَ ۟ۙ",
