      "arFull": "وَلِلّٰهِ یَسْجُدُ مَا فِی السَّمٰوٰتِ وَمَا فِی الْاَرْضِ مِنْ دَآبَّةٍ وَّالْمَلٰٓىِٕكَةُ وَهُمْ لَا یَسْتَكْبِرُوْنَ ۟",
