      "arFull": "اَلَمْ یَرَوْا اِلَی الطَّیْرِ مُسَخَّرٰتٍ فِیْ جَوِّ السَّمَآءِ ؕ مَا یُمْسِكُهُنَّ اِلَّا اللّٰهُ ؕ اِنَّ فِیْ ذٰلِكَ لَاٰیٰتٍ لِّقَوْمٍ یُّؤْمِنُوْنَ ۟",
