      "number": 104,
      "arFull": "اِنَّ الَّذِیْنَ لَا یُؤْمِنُوْنَ بِاٰیٰتِ اللّٰهِ ۙ لَا یَهْدِیْهِمُ اللّٰهُ وَلَهُمْ عَذَابٌ اَلِیْمٌ ۟",
