      "number": 105,
      "arFull": "اِنَّمَا یَفْتَرِی الْكَذِبَ الَّذِیْنَ لَا یُؤْمِنُوْنَ بِاٰیٰتِ اللّٰهِ ۚ وَاُولٰٓىِٕكَ هُمُ الْكٰذِبُوْنَ ۟",
      "ur": "جھوٹ افترا تو وہی باندھتے ہیں جنہیں اللہ تعالیٰ کی آیتوں پر ایمان نہیں ہوتا۔ یہی لوگ جھوٹے ہیں.[1]",
      "en": "They only invent falsehood who do not believe in the verses of Allāh, and it is those who are the liars.",
      "footnotesUr": "[1] اور ہمارا پیغمبر تو ایمانداروں کا سردار اور ان کا قائد ہے، وہ کس طرح اللہ پر افترا باندھ سکتا ہے کہ یہ کتاب اللہ کی طرف سے اس پر نازل نہ ہوئی ہو، اور وہ یونہی کہہ دے کہ یہ کتاب مجھ پر اللہ کی طرف سے نازل ہوئی ہے۔ اس لئے جھوٹا ہمارا پیغمبر نہیں، یہ خود جھوٹے ہیں جو قرآن کے منزل من اللہ ہونے کے منکر ہیں۔",
