      "number": 116,
      "arFull": "وَلَا تَقُوْلُوْا لِمَا تَصِفُ اَلْسِنَتُكُمُ الْكَذِبَ هٰذَا حَلٰلٌ وَّهٰذَا حَرَامٌ لِّتَفْتَرُوْا عَلَی اللّٰهِ الْكَذِبَ ؕ اِنَّ الَّذِیْنَ یَفْتَرُوْنَ عَلَی اللّٰهِ الْكَذِبَ لَا یُفْلِحُوْنَ ۟ؕ",
      "ur": "کسی چیز کو اپنی زبان سے جھوٹ موٹ نہ کہہ دیا کرو کہ یہ حلال ہے اور یہ حرام ہے کہ اللہ پر جھوٹ بہتان باندھ لو[1] ، سمجھ لو کہ اللہ تعالیٰ پر بہتان بازی کرنے والے کامیابی سے محروم ہی رہتے ہیں.",
