      "arFull": "اُدْعُ اِلٰی سَبِیْلِ رَبِّكَ بِالْحِكْمَةِ وَالْمَوْعِظَةِ الْحَسَنَةِ وَجَادِلْهُمْ بِالَّتِیْ هِیَ اَحْسَنُ ؕ اِنَّ رَبَّكَ هُوَ اَعْلَمُ بِمَنْ ضَلَّ عَنْ سَبِیْلِهٖ وَهُوَ اَعْلَمُ بِالْمُهْتَدِیْنَ ۟",
      "ur": "اپنے رب کی راه کی طرف لوگوں کو حکمت اور بہترین نصیحت کے ساتھ بلایئے اور ان سے بہترین طریقے سے گفتگو کیجئے[1] ، یقیناً آپ کا رب اپنی راه سے بہکنے والوں کو بھی بخوبی جانتا ہے اور وه راه یافتہ لوگوں سے بھی پورا واقف ہے.[2]",
      "en": "Invite to the way of your Lord with wisdom and good instruction, and argue with them in a way that is best. Indeed, your Lord is most knowing of who has strayed from His way, and He is most knowing of who is [rightly] guided.",
      "footnotesUr": "[1] اس میں تبلیغ ودعوت کے اصول بیان کئے گئے ہیں جو حکمت، ﻣﻮﻋﻈﮧ ﺣﺴﻨﮧ ﺍﻭﺭ ﺭﻓﻖ ﻭﻣﻼﺋﻤﺖ پر مبنی ہیں۔ جدال بالأحسن، درشتی اور تلخی سے بچتے ہوئے نرم ومشفقانہ لب ولہجہ اختیار کرنا ہے۔\n[2] یعنی آپ کا کام مذکورہ اصولوں کے مطابق وعظ و تبلیغ ہے، ہدایت کے راستے پر چلا دینا، یہ صرف اللہ کے اختیار میں ہے، اور وہ جانتا ہے کہ ہدایت قبول کرنے والا کون ہے اور کون نہیں؟",
      "footnotesEn": null,
